with scored as (select id, location, budget, lag(budget) over w_grp as prev_budget, lead(budget) over w_grp as next_budget, row_number() over w_grp as seq_no, lead(budget, 1) over (partition by location order by budget asc, id asc) as next_budget_2 from departments window w_grp as (partition by dept_name order by budget asc, id asc)), with_windows as (select id, location, budget, next_budget_2, lag(prev_budget, 1, 0) over (partition by location order by next_budget asc, id asc) as prev_prev_budget, avg(next_budget_2) over (partition by location order by next_budget asc, id asc rows between 6 preceding and 1 preceding) as next_budget_2_avg_6_prior, ntile(10) over (partition by location order by prev_budget desc, id asc) as prev_budget_bucket from scored), deduped as (select id, location, budget, prev_prev_budget, prev_budget_bucket from (select *, row_number() over (partition by location order by next_budget_2_avg_6_prior desc nulls first, id asc) as latest_rank from with_windows) t where latest_rank = 1), enriched as (select *, sum(prev_budget_bucket) over w_hist as running_sum_prev_budget_bucket, max(prev_budget_bucket) over w_hist as running_max_prev_budget_bucket, min(prev_budget_bucket) over w_hist as running_min_prev_budget_bucket, round(prev_prev_budget / sum(prev_prev_budget) over (partition by location), 4) as prev_prev_budget_share from deduped window w_hist as (partition by location order by budget asc, id asc rows between unbounded preceding and current row)), ranked as (select *, rank() over (partition by location order by prev_budget_bucket desc) as rank_in_group from enriched qualify rank_in_group = 1), latest_match as (select s.id, s.location, s.budget, s.prev_prev_budget, s.prev_budget_bucket, s.running_sum_prev_budget_bucket, s.running_max_prev_budget_bucket, s.prev_prev_budget_share, x.employee_job_title, x.employee_level from ranked s left join lateral (select c.job_title as employee_job_title, c.level as employee_level from employees c where c.dept_id = s.id order by c.hire_date desc, c.id desc limit 1) x on true), eligible as (select s.* from latest_match s where not exists (select 1 from employees c where c.dept_id = s.id and c.email like '%@startup.io')) select id, prev_budget_bucket, running_sum_prev_budget_bucket, running_max_prev_budget_bucket, employee_job_title, case when employee_job_title rlike '^(Manager|Designer)$' then 'CORE' when employee_job_title rlike '^(Engineer|Analyst)$' then 'OTHER_ZONE' else 'PRIORITY' end as employee_job_title_zone from eligible order by employee_job_title_zone desc;
